insert into public.question_bank (question_id,version,section,construct,question_type,prompt_en,prompt_fa,options,scoring,sort_order,active,weight) values
('RT01','v1','risk_tolerance','risk_preference','single_choice','Which investment feels most like you?','کدام سرمایه‌گذاری بیشتر شبیه شماست؟','[{"value":"A","label":"6% expected return, very low volatility"},{"value":"B","label":"10% expected return, moderate volatility"},{"value":"C","label":"16% expected return, high volatility"},{"value":"D","label":"25% expected return, very high volatility"}]','{"A":20,"B":45,"C":75,"D":100}',1,true,1),
('RT02','v1','risk_tolerance','loss_tolerance','single_choice','An investment falls 20%, but your original thesis has not changed. What do you do?','یک سرمایه‌گذاری ۲۰٪ افت کرده، اما تحلیل اولیه شما هنوز تغییری نکرده است. چه می‌کنید؟','[{"value":"A","label":"Sell most or all"},{"value":"B","label":"Sell part to reduce risk"},{"value":"C","label":"Hold"},{"value":"D","label":"Add to the position"}]','{"A":10,"B":35,"C":70,"D":100}',2,true,1.2),
('RT03','v1','risk_tolerance','risk_reward','single_choice','Which trade-off would you choose?','کدام رابطه ریسک و بازده را انتخاب می‌کنید؟','[{"value":"A","label":"90% chance to gain $5,000; 10% chance to lose $1,000"},{"value":"B","label":"60% chance to gain $12,000; 40% chance to lose $6,000"},{"value":"C","label":"I would need more information"}]','{"A":35,"B":90,"C":50}',3,true,1),
('RT04','v1','risk_tolerance','risk_preference','single_choice','Which statement best describes your investment attitude?','کدام جمله نگرش شما به سرمایه‌گذاری را بهتر توصیف می‌کند؟','[{"value":"A","label":"Protecting my capital comes first"},{"value":"B","label":"I accept some risk for better returns"},{"value":"C","label":"I am comfortable with significant volatility"},{"value":"D","label":"I accept severe drawdowns for substantial upside"}]','{"A":15,"B":45,"C":75,"D":100}',4,true,1),
('RT05','v1','risk_tolerance','patience','single_choice','Your investment has been flat for 18 months while other markets rise. What is your most likely reaction?','سرمایه‌گذاری شما ۱۸ ماه بدون رشد مانده، در حالی که بازارهای دیگر رشد کرده‌اند. واکنش محتمل شما چیست؟','[{"value":"A","label":"Sell and move on"},{"value":"B","label":"Review it and may reduce the position"},{"value":"C","label":"Stay invested if the thesis remains valid"},{"value":"D","label":"Look for an opportunity to add"}]','{"A":25,"B":45,"C":75,"D":90}',5,true,0.6),
('RT06','v1','risk_tolerance','volatility_comfort','single_choice','How comfortable are you with a portfolio that can fluctuate between -15% and +25% over a year?','با پرتفویی که ممکن است در یک سال بین ۱۵٪- تا ۲۵٪+ نوسان کند چقدر راحت هستید؟','[{"value":"A","label":"Very uncomfortable"},{"value":"B","label":"Somewhat uncomfortable"},{"value":"C","label":"Comfortable"},{"value":"D","label":"Very comfortable"}]','{"A":10,"B":40,"C":75,"D":100}',6,true,1),
('RT07','v1','risk_tolerance','crash_response','single_choice','The market suddenly drops 30%. What is your most likely first reaction?','بازار ناگهان ۳۰٪ سقوط می‌کند. اولین واکنش محتمل شما چیست؟','[{"value":"A","label":"Sell quickly to stop further losses"},{"value":"B","label":"Wait and reassess before acting"},{"value":"C","label":"Hold through the decline"},{"value":"D","label":"Look for opportunities to buy"}]','{"A":10,"B":45,"C":75,"D":100}',7,true,1),
('RT08','v1','risk_tolerance','risk_reward','single_choice','When choosing between a safer investment and a riskier one, what matters most to you?','هنگام انتخاب بین یک سرمایه‌گذاری امن‌تر و یک گزینه پرریسک‌تر، چه چیزی برای شما مهم‌تر است؟','[{"value":"A","label":"Avoiding the possibility of loss"},{"value":"B","label":"Balancing risk and return"},{"value":"C","label":"Maximizing expected return"},{"value":"D","label":"Capturing the biggest possible upside"}]','{"A":15,"B":50,"C":80,"D":100}',8,true,1),
('RT09','v1','risk_tolerance','emotional_reactivity','single_choice','When an investment moves sharply against you, how strongly does it affect your emotions?','وقتی یک سرمایه‌گذاری به‌شدت برخلاف انتظار شما حرکت می‌کند، چقدر از نظر احساسی تحت تأثیر قرار می‌گیرید؟','[{"value":"A","label":"Very strongly"},{"value":"B","label":"Moderately"},{"value":"C","label":"A little"},{"value":"D","label":"Hardly at all"}]','{"A":10,"B":40,"C":75,"D":100}',9,true,0.8),
('RT10','v1','risk_tolerance','past_risk_behavior','single_choice','Which best describes your past investment behaviour?','کدام گزینه رفتار گذشته شما در سرمایه‌گذاری را بهتر توصیف می‌کند؟','[{"value":"A","label":"I usually avoid large risks"},{"value":"B","label":"I sometimes took more risk than I later felt comfortable with"},{"value":"C","label":"I have knowingly accepted substantial risk"},{"value":"D","label":"I have knowingly taken very large risks for high upside"}]','{"A":15,"B":45,"C":75,"D":100}',10,true,1),
('BD01','v1','behavioral_dna','risk_perception','single_choice','When you hear “high-risk investment,” what comes to mind first?','وقتی عبارت «سرمایه‌گذاری پرریسک» را می‌شنوید، اولین چیزی که به ذهنتان می‌رسد چیست؟','[{"value":"A","label":"High probability of losing money"},{"value":"B","label":"Large price fluctuations"},{"value":"C","label":"High uncertainty"},{"value":"D","label":"A potentially missed opportunity if I avoid it"}]','{"A":25,"B":50,"C":70,"D":90}',11,true,1),
('BD02','v1','behavioral_dna','risk_perception','single_choice','Two investments can both fall 20%. Does that mean they are equally risky?','دو سرمایه‌گذاری هر دو می‌توانند ۲۰٪ افت کنند. آیا این یعنی ریسک هر دو دقیقاً یکسان است؟','[{"value":"A","label":"Yes"},{"value":"B","label":"Not necessarily"},{"value":"C","label":"It depends on probability, liquidity and other factors"}]','{"A":20,"B":70,"C":100}',12,true,1),
('BD03','v1','behavioral_dna','self_confidence','scale','How confident are you in your own investment decision-making?','چقدر به توانایی خودتان در تصمیم‌گیری سرمایه‌گذاری اعتماد دارید؟','[]','{"scale":{"min":0,"max":10,"direction":"direct"}}',13,true,1),
('BD04','v1','behavioral_dna','overconfidence','scale','How confident are you that your investment decisions will outperform the market?','چقدر مطمئن هستید که تصمیم‌های سرمایه‌گذاری شما بهتر از بازار عمل خواهند کرد؟','[]','{"scale":{"min":0,"max":10,"direction":"direct"}}',14,true,1),
('BD05','v1','behavioral_dna','calibration','single_choice','If you say you are 80% confident in a prediction, how often do you expect such predictions to be correct?','اگر در یک پیش‌بینی ۸۰٪ اطمینان دارید، انتظار دارید چنین پیش‌بینی‌هایی چند درصد مواقع درست از آب دربیایند؟','[{"value":"A","label":"Around 50%"},{"value":"B","label":"Around 65%"},{"value":"C","label":"Around 80%"},{"value":"D","label":"Almost always"}]','{"A":25,"B":55,"C":85,"D":60}',15,true,1),
('BD06','v1','behavioral_dna','social_influence','scale','How strongly do other people’s investment success stories influence your decisions?','موفقیت‌های سرمایه‌گذاری دیگران چقدر روی تصمیم‌های شما اثر می‌گذارد؟','[]','{"scale":{"min":0,"max":10,"direction":"direct"}}',16,true,1),
('BD07','v1','behavioral_dna','recency_bias','single_choice','An asset has risen 40% over the last year. Does it feel more attractive to you now?','یک دارایی طی یک سال ۴۰٪ رشد کرده است. آیا حالا برای شما جذاب‌تر به نظر می‌رسد؟','[{"value":"A","label":"Much less attractive"},{"value":"B","label":"About the same"},{"value":"C","label":"Somewhat more attractive"},{"value":"D","label":"Much more attractive"}]','{"A":100,"B":70,"C":40,"D":10}',17,true,1),
('BD08','v1','behavioral_dna','anchoring','single_choice','You bought an investment at $100 and it is now $60. Which number is most psychologically important to you?','یک سرمایه‌گذاری را با قیمت ۱۰۰ دلار خریده‌اید و حالا ۶۰ دلار است. کدام عدد از نظر ذهنی برای شما مهم‌تر است؟','[{"value":"A","label":"$100 purchase price"},{"value":"B","label":"$60 current price"},{"value":"C","label":"The investment’s current fundamental value"}]','{"A":15,"B":55,"C":100}',18,true,1),
('BD09','v1','behavioral_dna','confirmation_bias','single_choice','Your data supports an investment, but three credible analysts disagree. What do you do?','داده‌های شما از یک سرمایه‌گذاری حمایت می‌کنند، اما سه تحلیلگر معتبر مخالف‌اند. چه می‌کنید؟','[{"value":"A","label":"Ignore them because my analysis is strong"},{"value":"B","label":"Consider their views but probably keep my position"},{"value":"C","label":"Actively test my thesis against their arguments"},{"value":"D","label":"Abandon my view immediately"}]','{"A":10,"B":45,"C":100,"D":60}',19,true,1),
('BD10','v1','behavioral_dna','regret_sensitivity','scale','How strongly would regret affect your next investment decision after selling and then watching the asset rise 20%?','اگر یک دارایی را بفروشید و بعد ۲۰٪ رشد کند، پشیمانی چقدر روی تصمیم سرمایه‌گذاری بعدی شما اثر می‌گذارد؟','[]','{"scale":{"min":0,"max":10,"direction":"direct"}}',20,true,1),
('BD11','v1','behavioral_dna','disposition_effect','single_choice','When an investment has gained significantly, what are you most likely to do?','وقتی یک سرمایه‌گذاری سود قابل‌توجهی کرده، معمولاً چه می‌کنید؟','[{"value":"A","label":"Sell to lock in the gain"},{"value":"B","label":"Sell part and keep part"},{"value":"C","label":"Hold if the thesis remains strong"},{"value":"D","label":"Add if the outlook improved"}]','{"A":15,"B":45,"C":80,"D":100}',21,true,1),
('BD12','v1','behavioral_dna','adaptability','single_choice','New evidence contradicts an investment you previously liked. What is your reaction?','شواهد جدید با سرمایه‌گذاری‌ای که قبلاً دوست داشتید در تضاد است. واکنش شما چیست؟','[{"value":"A","label":"I usually defend my original view"},{"value":"B","label":"I become cautious"},{"value":"C","label":"I reassess the thesis"},{"value":"D","label":"I quickly change course when evidence warrants it"}]','{"A":10,"B":45,"C":80,"D":100}',22,true,1),
('BD13','v1','behavioral_dna','financial_self_efficacy','scale','How capable do you feel of understanding financial and investment information?','چقدر خودتان را در درک اطلاعات مالی و سرمایه‌گذاری توانمند می‌دانید؟','[]','{"scale":{"min":0,"max":10,"direction":"direct"}}',23,true,1),
('BD14','v1','behavioral_dna','emotional_reactivity','scale','During major market moves, how difficult is it for you to stick to a pre-planned strategy?','در نوسانات شدید بازار، پایبندی به استراتژی از پیش تعیین‌شده برای شما چقدر دشوار است؟','[]','{"scale":{"min":0,"max":10,"direction":"reverse"}}',24,true,1),
('BD15','v1','behavioral_dna','opportunity_sensitivity','single_choice','A new investment opportunity appears during a market sell-off. What attracts you most?','در زمان ریزش بازار یک فرصت جدید ظاهر می‌شود. چه چیزی بیشتر شما را جذب می‌کند؟','[{"value":"A","label":"The chance to avoid further loss"},{"value":"B","label":"Evidence that the price is attractive"},{"value":"C","label":"The potential for strong future returns"},{"value":"D","label":"The opportunity to buy when others are fearful"}]','{"A":20,"B":55,"C":80,"D":100}',25,true,1),
('RC01','v1','risk_capacity','income','single_choice','What is your approximate annual household income?','درآمد سالانه تقریبی خانوار شما چقدر است؟','[{"value":"A","label":"Under $40,000"},{"value":"B","label":"$40,000–$79,999"},{"value":"C","label":"$80,000–$149,999"},{"value":"D","label":"$150,000+"}]','{"A":20,"B":45,"C":75,"D":100}',26,true,1),
('RC02','v1','risk_capacity','income_stability','single_choice','How stable is your household income?','درآمد خانوار شما چقدر باثبات است؟','[{"value":"A","label":"Highly variable or uncertain"},{"value":"B","label":"Somewhat variable"},{"value":"C","label":"Mostly stable"},{"value":"D","label":"Very stable"}]','{"A":15,"B":40,"C":75,"D":100}',27,true,1.2),
('RC03','v1','risk_capacity','investable_assets','single_choice','Approximately how much do you have in investable financial assets?','تقریباً چه میزان دارایی مالی قابل سرمایه‌گذاری دارید؟','[{"value":"A","label":"Under $25,000"},{"value":"B","label":"$25,000–$99,999"},{"value":"C","label":"$100,000–$499,999"},{"value":"D","label":"$500,000+"}]','{"A":15,"B":40,"C":75,"D":100}',28,true,1.2),
('RC04','v1','risk_capacity','debt','single_choice','How would you describe your current debt burden?','وضعیت بدهی فعلی خود را چگونه توصیف می‌کنید؟','[{"value":"A","label":"High; it materially limits my finances"},{"value":"B","label":"Moderate"},{"value":"C","label":"Low"},{"value":"D","label":"Very low or no significant debt"}]','{"A":10,"B":40,"C":75,"D":100}',29,true,1),
('RC05','v1','risk_capacity','emergency_reserve','single_choice','How long could your emergency savings cover essential expenses?','پس‌انداز اضطراری شما چند ماه هزینه‌های ضروری را پوشش می‌دهد؟','[{"value":"A","label":"Less than 1 month"},{"value":"B","label":"1–3 months"},{"value":"C","label":"3–6 months"},{"value":"D","label":"More than 6 months"}]','{"A":10,"B":40,"C":75,"D":100}',30,true,1.2),
('RC06','v1','risk_capacity','dependents','single_choice','How many people financially depend on your income?','چند نفر از نظر مالی به درآمد شما وابسته‌اند؟','[{"value":"A","label":"4 or more"},{"value":"B","label":"2–3"},{"value":"C","label":"1"},{"value":"D","label":"None"}]','{"A":20,"B":45,"C":75,"D":100}',31,true,0.8),
('RC07','v1','risk_capacity','loss_impact','single_choice','If your investment portfolio fell 20%, how materially would that affect your day-to-day life?','اگر پرتفوی شما ۲۰٪ افت کند، این افت چقدر روی زندگی روزمره شما اثر می‌گذارد؟','[{"value":"A","label":"It would seriously affect my ability to meet obligations"},{"value":"B","label":"It would require meaningful lifestyle changes"},{"value":"C","label":"It would be uncomfortable but manageable"},{"value":"D","label":"It would have little practical impact"}]','{"A":5,"B":35,"C":70,"D":100}',32,true,1.5),
('RC08','v1','risk_capacity','concentration','single_choice','Approximately what share of your total financial assets would be represented by this investment?','تقریباً چه سهمی از کل دارایی‌های مالی شما در این سرمایه‌گذاری قرار می‌گیرد؟','[{"value":"A","label":"More than 50%"},{"value":"B","label":"25%–50%"},{"value":"C","label":"10%–25%"},{"value":"D","label":"Less than 10%"}]','{"A":10,"B":40,"C":75,"D":100}',33,true,1),
('RC09','v1','risk_capacity','financial_resources','single_choice','If this investment lost 20%, what other financial resources would you have available?','اگر این سرمایه‌گذاری ۲۰٪ زیان بدهد، چه منابع مالی دیگری در اختیار دارید؟','[{"value":"A","label":"Very limited alternatives"},{"value":"B","label":"Some savings or resources"},{"value":"C","label":"Several meaningful financial resources"},{"value":"D","label":"Substantial resources outside this investment"}]','{"A":15,"B":45,"C":75,"D":100}',34,true,0.8),
('RC10','v1','risk_capacity','employment','single_choice','How secure is your primary source of income?','منبع اصلی درآمد شما چقدر امن و باثبات است؟','[{"value":"A","label":"Uncertain or at significant risk"},{"value":"B","label":"Somewhat uncertain"},{"value":"C","label":"Generally secure"},{"value":"D","label":"Highly secure"}]','{"A":15,"B":40,"C":75,"D":100}',35,true,1),
('RT07B','v1','risk_tolerance','crash_response','single_choice','After a major market decline, how likely are you to make a decision purely because you feel anxious?','پس از یک ریزش شدید بازار، چقدر احتمال دارد صرفاً به دلیل اضطراب تصمیم بگیرید؟','[{"value":"A","label":"Very likely"},{"value":"B","label":"Somewhat likely"},{"value":"C","label":"Unlikely"},{"value":"D","label":"Very unlikely"}]','{"A":10,"B":40,"C":75,"D":100}',36,true,0.8)
