alter table public.question_bank add column if not exists weight numeric not null default 1;

on conflict (question_id) do update set version=excluded.version, section=excluded.section, construct=excluded.construct, question_type=excluded.question_type, prompt_en=excluded.prompt_en, prompt_fa=excluded.prompt_fa, options=excluded.options, scoring=excluded.scoring, sort_order=excluded.sort_order, active=excluded.active, weight=excluded.weight;
